    12	import hotel.reservations.HotelException;
    13	import hotel.reservations.NewReservation;
    14	import hotel.reservations.ReservationService;
    15	import hotel.rooms.Rooms;
    16	import io.javalin.Javalin;
    17	import io.javalin.http.Context;
    18	import io.javalin.json.JavalinJackson;
    19	import java.sql.Connection;
    20	import java.sql.PreparedStatement;
    21	import java.time.LocalDate;
    22	import java.time.YearMonth;
    23	import java.time.format.DateTimeParseException;
    24	import javax.sql.DataSource;
    25	
    26	/** The HTTP API the inn's website and front desk call. */
    27	public final class HttpApi {
    28	
    29	    private final Javalin server;
    30	    private final DataSource dataSource;
    31	    private final Rooms rooms;
    32	    private final ReservationService reservations;
    33	    private final SentMessages sentMessages;
    34	    private final OccupancyReport occupancyReport;
    35	    private final RevenueReport revenueReport;
    36	
    37	    public HttpApi(
    38	            DataSource dataSource,
    39	            Rooms rooms,
    40	            ReservationService reservations,
    41	            SentMessages sentMessages,
    42	            OccupancyReport occupancyReport,
    43	            RevenueReport revenueReport) {
    44	        this.dataSource = dataSource;
    45	        this.rooms = rooms;
    46	        this.reservations = reservations;
    47	        this.sentMessages = sentMessages;
    48	        this.occupancyReport = occupancyReport;
    49	        this.revenueReport = revenueReport;
    50	
    51	        ObjectMapper jsonMapper = JsonMapper.builder()
    52	                .addModule(new JavaTimeModule())
    53	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    54	                .build();
    55	        this.server = Javalin.create(config -> {
    56	            config.showJavalinBanner = false;
    57	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    58	        });
    59	        registerRoutes();
    60	        registerErrorHandling();
    61	    }
    62	
    63	    public Javalin server() {
    64	        return server;
    65	    }
    66	
    67	    private void registerRoutes() {
    68	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    69	
    70	        server.post("/reservations", ctx -> {
    71	            NewReservation request = readNewReservation(ctx);
    72	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    73	        });
    74	        server.get("/reservations/{id}", ctx ->
    75	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    76	        server.post("/reservations/{id}/confirmation", ctx ->
    77	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    78	        server.post("/reservations/{id}/cancellation", ctx ->
    79	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
    80	        server.post("/reservations/{id}/check-in", ctx -> {
    81	            long id = reservationId(ctx);
    82	            try (Connection connection = dataSource.getConnection();
    83	                    PreparedStatement update = connection.prepareStatement(
    84	                            "UPDATE reservations SET status = 'CHECKED_IN' WHERE id = ? AND status = 'CONFIRMED'")) {
    85	                update.setLong(1, id);
    86	                if (update.executeUpdate() == 0) {
    87	                    throw new HotelException(ErrorCode.OPERATION_NOT_ALLOWED, "cannot check in reservation " + id
    88	                            + " while it is " + reservations.find(id).status());
    89	                }
    90	            }
    91	            ctx.json(new ReservationResponse(reservations.find(id)));
    92	        });
    93	        server.post("/reservations/{id}/check-out", ctx ->
    94	                ctx.json(reservations.checkOut(reservationId(ctx))));
    95	        server.get("/reservations/{id}/document", ctx ->
    96	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    97	
    98	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    99	
   100	        server.get("/reports/occupancy", ctx -> {
   101	            LocalDate night = readDate(ctx);
   102	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
   103	        });
   104	        server.get("/reports/revenue", ctx -> {
   105	            YearMonth month = readMonth(ctx);
   106	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
   107	        });
   108	    }
   109	
   110	    private void registerErrorHandling() {
   111	        server.exception(HotelException.class, (exception, ctx) -> {
   112	            ctx.status(httpStatus(exception.errorCode()));
   113	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   114	        });
   115	    }
   116	
   117	    private static int httpStatus(ErrorCode errorCode) {
   118	        return switch (errorCode) {
   119	            case INVALID_REQUEST -> 400;
   120	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   121	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   122	            case CAPACITY_EXCEEDED -> 422;
   123	        };
   124	    }
   125	
   126	    private static NewReservation readNewReservation(Context ctx) {
   127	        CreateReservationRequest body;
   128	        try {
   129	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   130	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   131	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   132	        }
   133	        if (body == null
   134	                || body.roomNumber() == null
   135	                || isBlank(body.guestName())
   136	                || isBlank(body.guestEmail())
   137	                || isBlank(body.guestCpf())
   138	                || body.checkIn() == null
   139	                || body.checkOut() == null
   140	                || body.guests() == null
   141	                || body.ratePlan() == null) {
   142	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   143	        }
   144	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   145	        return new NewReservation(body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(),
   146	                body.ratePlan(), body.companyCode());
   147	    }
   148	
   149	    private static long reservationId(Context ctx) {
   150	        String id = ctx.pathParam("id");
   151	        try {
   152	            return Long.parseLong(id);
   153	        } catch (NumberFormatException notANumber) {
   154	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   155	        }
   156	    }
   157	
   158	    private static LocalDate readDate(Context ctx) {
   159	        String date = requiredQueryParam(ctx, "date");
   160	        try {
   161	            return LocalDate.parse(date);
   162	        } catch (DateTimeParseException badDate) {
   163	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   164	        }
   165	    }
   166	
   167	    private static YearMonth readMonth(Context ctx) {
   168	        String month = requiredQueryParam(ctx, "month");
   169	        try {
   170	            return YearMonth.parse(month);
   171	        } catch (DateTimeParseException badMonth) {
   172	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   173	        }
   174	    }
   175	
   176	    private static String requiredQueryParam(Context ctx, String name) {
   177	        String value = ctx.queryParam(name);
   178	        if (value == null) {
   179	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   180	        }
   181	        return value;
   182	    }
   183	
   184	    private static boolean isBlank(String text) {
   185	        return text == null || text.isBlank();
   186	    }
   187	}
