     2	
     3	import static org.junit.jupiter.api.Assertions.assertEquals;
     4	import static org.junit.jupiter.api.Assertions.assertThrows;
     5	
     6	import hotel.EmptyDatabase;
     7	import hotel.messages.EmailSender;
