    10	import java.math.BigDecimal;
    11	import java.time.LocalDate;
    12	import org.junit.jupiter.api.AfterEach;
    13	import org.junit.jupiter.api.Test;
    14	
    15	class NewRatePlansTest {
    16	
    17	    private final EmptyDatabase database = new EmptyDatabase();
    18	    private final RatePlans ratePlans = new RatePlans();
    19	    private final ReservationService service = new ReservationService(new Rooms(database.dataSource()),
    20	            new ReservationStore(database.dataSource()), new PriceCalculator(ratePlans), ratePlans,
    21	            new EmailSender(new SentMessages(database.dataSource())));
    22	
    23	    @AfterEach
    24	    void closeDatabase() {
    25	        database.close();
    26	    }
    27	
    28	    private Reservation book(int room, String checkIn, String checkOut, RatePlan plan, String companyCode) {
    29	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
    30	        return service.create(new NewReservation(
    31	                room, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, plan, companyCode));
    32	    }
    33	
    34	    private BigDecimal refundAfterPaying(Reservation reservation) {
    35	        service.confirm(reservation.id());
    36	        return service.cancel(reservation.id()).refund();
    37	    }
    38	
    39	    private static ErrorCode errorOf(Runnable action) {
    40	        return assertThrows(HotelException.class, action::run).errorCode();
    41	    }
    42	
    43	    @Test
    44	    void eachCompanyHasItsOwnDiscount() {
    45	        Reservation tecnosul = book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "TECNOSUL");
    46	        Reservation agrovale = book(202, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "AGROVALE");
    47	        Reservation farmavida = book(201, "2027-03-20", "2027-03-22", RatePlan.CORPORATE, "FARMAVIDA");
    48	
    49	        assertEquals(new BigDecimal("779.80"), tecnosul.price().subtotal());
    50	        assertEquals(new BigDecimal("93.58"), tecnosul.price().discount());
    51	        assertEquals(new BigDecimal("686.22"), tecnosul.price().total());
    52	        assertEquals(new BigDecimal("140.36"), agrovale.price().discount());
    53	        assertEquals(new BigDecimal("639.44"), agrovale.price().total());
    54	        assertEquals(new BigDecimal("194.95"), farmavida.price().discount());
    55	        assertEquals(new BigDecimal("584.85"), farmavida.price().total());
    56	    }
    57	
    58	    @Test
    59	    void corporateNeedsAKnownCompanyAndGivesEverythingBack() {
    60	        assertEquals(ErrorCode.INVALID_REQUEST,
    61	                errorOf(() -> book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, null)));
    62	        assertEquals(ErrorCode.INVALID_REQUEST,
    63	                errorOf(() -> book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "ACME")));
    64	
    65	        Reservation reservation = book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "TECNOSUL");
    66	        assertEquals(new BigDecimal("686.22"), refundAfterPaying(reservation));
    67	    }
    68	
    69	    @Test
    70	    void theWeekendPackageIsAFixedPricePerRoomTypeAllYear() {
    71	        Reservation deluxe = book(201, "2027-03-12", "2027-03-14", RatePlan.WEEKEND_PACKAGE, null);
    72	        Reservation standard = book(101, "2027-03-19", "2027-03-21", RatePlan.WEEKEND_PACKAGE, null);
    73	        Reservation suite = book(301, "2027-03-19", "2027-03-21", RatePlan.WEEKEND_PACKAGE, null);
    74	        Reservation july = book(202, "2027-07-09", "2027-07-11", RatePlan.WEEKEND_PACKAGE, null);
    75	
    76	        assertEquals(new BigDecimal("820.00"), deluxe.price().subtotal());
    77	        assertEquals(new BigDecimal("0.00"), deluxe.price().discount());
    78	        assertEquals(new BigDecimal("820.00"), deluxe.price().total());
    79	        assertEquals(new BigDecimal("520.00"), standard.price().total());
    80	        assertEquals(new BigDecimal("1200.00"), suite.price().total());
    81	        assertEquals(new BigDecimal("820.00"), july.price().total());
    82	        assertEquals(new BigDecimal("410.00"), refundAfterPaying(deluxe));
    83	    }
    84	
    85	    @Test
    86	    void theWeekendPackageGoesFromFridayToTheSundayRightAfter() {
    87	        assertEquals(ErrorCode.INVALID_REQUEST,
    88	                errorOf(() -> book(202, "2027-03-13", "2027-03-15", RatePlan.WEEKEND_PACKAGE, null)));
    89	        assertEquals(ErrorCode.INVALID_REQUEST,
    90	                errorOf(() -> book(202, "2027-03-26", "2027-03-29", RatePlan.WEEKEND_PACKAGE, null)));
    91	        assertEquals(ErrorCode.INVALID_REQUEST,
    92	                errorOf(() -> book(202, "2027-03-12", "2027-03-13", RatePlan.WEEKEND_PACKAGE, null)));
    93	    }
    94	
    95	    @Test
    96	    void theLongStayTakesTenPercentOffAndKeepsTheHighSeason() {
    97	        Reservation march = book(101, "2027-03-01", "2027-03-08", RatePlan.LONG_STAY, null);
    98	        Reservation summer = book(102, "2027-06-28", "2027-07-05", RatePlan.LONG_STAY, null);
    99	
   100	        assertEquals(new BigDecimal("1749.30"), march.price().subtotal());
   101	        assertEquals(new BigDecimal("174.93"), march.price().discount());
   102	        assertEquals(new BigDecimal("1574.37"), march.price().total());
   103	        // June 28 to 30 at 249.90, July 1 to 4 at 299.88
   104	        assertEquals(new BigDecimal("1949.22"), summer.price().subtotal());
   105	        assertEquals(new BigDecimal("1754.30"), summer.price().total());
   106	        assertEquals(new BigDecimal("1574.37"), refundAfterPaying(march));
   107	    }
   108	
   109	    @Test
   110	    void theLongStayNeedsSevenNights() {
   111	        assertEquals(ErrorCode.INVALID_REQUEST,
   112	                errorOf(() -> book(102, "2027-04-01", "2027-04-07", RatePlan.LONG_STAY, null)));
   113	    }
   114	
   115	    @Test
   116	    void theCompanyCodeIsIgnoredOutsideCorporate() {
   117	        Reservation reservation = book(102, "2027-05-10", "2027-05-12", RatePlan.STANDARD, "TECNOSUL");
   118	
   119	        assertEquals(new BigDecimal("0.00"), reservation.price().discount());
   120	        assertEquals(new BigDecimal("0.00"), service.find(reservation.id()).price().discount());
   121	    }
   122	}
